const float FOCAL_LENGTH = 1.2;
const int MAX_RAY_STEPS = 1000;
const int MAX_SHADOW_STEPS = 50;
const int MAX_REFLECTIONS = 10;
const float MIN_RAY_DIST = 0.001;
const float MAX_RAY_DIST = 100.;
const float RAY_PRECISION = 0.00001;
const float NORMAL_PRECISION = 0.0001;
const float SHADOW_DARKNESS = 0.5;
const float SHADOW_HARDNESS = 50.0;

const float SATURATION = 3.5;
const float GAMMA = 1.75;

vec3 lightPos = vec3(10.,7.,5.);

vec3 move(vec3 point, vec3 delta){
    return point - delta;
}

mat2 rotation(float angle){
    float s=sin(angle), c=cos(angle);
    return mat2(c, -s, s, c);
}

float sdPlane(vec3 p, float h){
    return p.y - h;
}

float sdSphere(vec3 p, float r){
    return length(p) - r;
}

float sdBox(vec3 p, vec3 b){
    vec3 d = abs(p) - b;
    return length(max(d, 0.)) + min(max(d.x, max(d.y, d.z)), 0.);
}

float sdTorus(vec3 p, vec2 r){
    vec2 q = vec2(length(p.xz) - r.x, p.y);
    return length(q) - r.y;
}

float sdCylinder(vec3 p, vec3 h) {
    vec2 d = vec2(length(p.xz) - h.x, abs(p.y) - h.y);
    return min(max(d.x, d.y), 0.0) + length(max(d, 0.0));
}

float sdCone(vec3 p, vec3 h) {
    float r = h.x * (1.0 - p.y / h.y);
    float q = length(p.xz) - r;
    return (p.y > 0.0 && p.y < h.y) ? max(q, p.y - h.y) : length(p);
}

vec2 opUnion(vec2 d1, vec2 d2){
    return (d1.x<d2.x) ? d1 : d2;
}

vec2 opSmoothUnionMix(float d1, float d2, float k){
    float h = max(k-abs(d1-d2), 0.0)/k;
    float m = h*h*h*0.5;
    float s = m*k*(1.0/3.0);
    return (d1<d2) ? vec2(d1-s, m) : vec2(d2-s, 1.0-m);
}

vec2 sceneDist(vec3 p){
    vec3 q;
    vec2 res = vec2(1e10, 0.);

    // floor
    res = opUnion(res, vec2(sdPlane(p, -1.75), 0.));

    // ring
    q = move(p.xzy, vec3(-1,-1,1.275));
    if(max(abs(q.x), max(abs(q.y), abs(q.z))) < 3.5){
        float d3= sdTorus(q, vec2(1.0,0.1));
        q = move(p.xzy, vec3(-1,-1,-0.8));
        float d4 = sdBox(q, vec3(0.1,0.1,1.0));
        vec2 r = opSmoothUnionMix(d3, d4, 0.5);
        r.y = 1.;
        res = opUnion(res, r);
    }

    // bubbles
    q = move(p, vec3(-1,1.3,-1));
    if(max(abs(q.x), max(abs(q.y) * 0.5, abs(q.z))) < 40.0){
        //blown
        float d1 = sdCone(q.xzy, vec3(0.95, -1.0*(sin(-1.0*iTime*2.0)+sin(-1.0*iTime*4.0)*0.5), 0.0));
        float d2 = sdSphere(move(q,vec3(sin(iTime*5.0)*0.1,sin(-1.0*iTime*4.0)*0.15+sin(iTime*9.0)*0.05, sin(-1.0*iTime*2.0)+sin(-1.0*iTime*4.0)*0.5+sin(-1.0*iTime*8.0)*0.25+2.3)), 1.1);
        vec2 r = opSmoothUnionMix(d1, d2, 1.8);

        r.y = 2.;
        res = opUnion(res, r);

        //floating
        float d5 = sdSphere(move(q,vec3(sin(iTime*0.6)*0.18,sin(iTime*0.45)*0.8-0.8,sin(iTime*0.8)*0.9-4.0)), 0.7);
        float d6 = sdSphere(move(q,vec3(sin(iTime*0.3)*2.0-5.0,-sin(iTime*0.4)*0.9+1.0, sin(iTime*0.1)*3.2-0.8)), 1.1);
        r = opSmoothUnionMix(d5, d6, 0.0);

        r.y = 2.;
        res = opUnion(res, r);

        //deforming
        float d7 = sdSphere(move(q,vec3(sin(iTime*0.34-1.0)*0.2-sin(iTime*0.13)*0.28,sin(iTime*0.7)*0.45+0.6,sin(iTime*0.57)*0.6-sin(iTime*0.3)*0.3+5.7)), 0.1);
        float d8 = sdSphere(move(q,vec3(sin(iTime*0.34-1.0)*0.194,sin(iTime*0.6)*0.29+sin(iTime*0.2)*0.2+0.6,sin(iTime*0.6)*0.6+5.76)), 0.2);
        r = opSmoothUnionMix(d7, d8, 5.0);

        r.y = 2.;
        res = opUnion(res, r);

   }

    return res;
}

vec2 rayMarch(vec3 ro, vec3 rd, float exterior){
    vec2 res;
    float depth = MIN_RAY_DIST;
    for(int i = 0; i < MAX_RAY_STEPS; i++){
        vec3 p = ro + depth * rd;
        res = sceneDist(p);
        float d = res.x * exterior * 0.5;
        if(d < RAY_PRECISION)
            break;
        depth += d;
        if(depth >= MAX_RAY_DIST)
            return vec2(MAX_RAY_DIST, -1.);
    }
    return vec2(depth, res.y);
}

vec3 getNormal(vec3 p){
  vec2 e = vec2(1.0, -1.0);
  vec2 ee = e * NORMAL_PRECISION;
  return normalize(
        e.xyy * sceneDist(p + ee.xyy).x +
        e.yxy * sceneDist(p + ee.yxy).x +
        e.yyx * sceneDist(p + ee.yyx).x +
        e.xxx * sceneDist(p + ee.xxx).x);
}

float getAmbientOcclusion(vec3 ro, vec3 rd){
    float occ = 0.;
    float sca = 1.;
    for(int i = 0; i < 5; i++){
        float depth = 0.01 + 0.02 * float(i * i);
        float d = abs(sceneDist(ro + depth * rd).x);
        occ += max(depth - d, 0.) * sca;
        sca *= 0.75;
    }
    return clamp(1. - 2.5 * occ, 0., 1.);
}

float getShadow(vec3 ro, vec3 rd){
    float exposure = 1.;
    float depth = MIN_RAY_DIST;
    for(int i = 0; i < MAX_SHADOW_STEPS; i++){
        vec3 p = ro + depth * rd;
        float d = sceneDist(p).x;
        if (d < RAY_PRECISION) return 1. - SHADOW_DARKNESS;
        if (d < 0.01) i--;
        exposure = min(exposure, d / depth);
        depth += d;
        if(depth >= MAX_RAY_DIST) break;
    }
    exposure = clamp(exposure * SHADOW_HARDNESS, 0., 1.);
    return mix(1., exposure, SHADOW_DARKNESS);
}

vec3 refract2(vec3 I, vec3 N, float eta){
    float k = 1.0 - eta * eta * (1.0 - dot(N, I) * dot(N, I));
    if (k < 0.0) return reflect(I, N); // total internal reflection
    return eta * I - (eta * dot(N, I) + sqrt(k)) * N;
}

vec2 normalizeCoords(vec2 p){
    return (2.0*p-iResolution.xy)/iResolution.x;
}

vec3 getColor(vec3 ro, vec3 rd, vec2 fc){
    vec3 totCol = vec3(0);
    float mixFactor = 1.;
    float exterior;

    for(int i=0; i<MAX_REFLECTIONS; i++){
        exterior = sign(sceneDist(ro).x);
        vec2 res = rayMarch(ro, rd, exterior);
        float d = res.x;
        float m = res.y;
        vec3 p = ro + rd * d;
        vec3 n = getNormal(p) * exterior;

        // material properties
        vec3 col;
        float reflectivity = 0.;
        float refractivity = 0.;
        float refractionIndex = 0.;
        float specularFactor = 0.;
        float specularAlpha = 0.;
        float fresnelCoeff = 0.;
        if(m < -0.5){ // sky
            vec2 uv = normalizeCoords(fc);
            col = 0.7 + 0.2 * cos(iTime + uv.xyx + vec3(6, 5, 4));

        }
        else if (m < 0.5){ // floor
            col = vec3(0.3 + 0.7*mod(floor(p.x*0.5) + floor(p.z*0.5), 2.0));
            reflectivity = 0.1;
            refractivity = 0.1;
            refractionIndex = 0.3;
            specularFactor = 0.85;
            specularAlpha = 5.;
            fresnelCoeff = 0.;
        }
        else if(m < 1.001){ // ring
            col = mix(vec3(0.7, 0.18, 0.18), vec3(0.8, 0.1, 0.18), m-1.);
            reflectivity = 0.1;
            refractivity = 0.01;
            refractionIndex = 1./1.01;
            specularFactor = 1.85;
            specularAlpha = 10.;
            fresnelCoeff = 0.1;
        }
        else{ // bubble
            col = vec3(0.3, 0.4, 0.6);
            //col = Cells(uv, vec2(0.0), 10.0, 0.5, 0.0001).xyz;
            reflectivity = -0.1;
            refractivity =2.05;
            refractionIndex = 1.05;
            specularFactor = 1.2;
            specularAlpha = 3.0;
            fresnelCoeff = 1.1;
        }

        // lighting and shading
        if(m > -0.5){
            vec3 lightDir = normalize(lightPos - p);

            // ambient occlusion
            float occ = getAmbientOcclusion(p, n);
            col *= occ;

            // smooth shadow
            float shadow = getShadow(p, lightDir);
            col *= shadow;

            // diffuse lighting
            float diffuse = dot(n, lightDir)*.5 + .5;

            // specular lighting
            float specular = clamp(dot(reflect(rd, n), lightDir), 0., 1.);
            specular = pow(specular, specularAlpha);

            // fresnel factor
            float fCoeff = 0.6;
            float fresnel = mix(pow(1. - dot(n, lightDir), 5.), 1., fCoeff);

            col *= diffuse + specular * specularFactor + fresnel * fresnelCoeff;

            // distance attenuation
            float lightDist = dot(lightPos - p, lightPos - p);
            col *= smoothstep(50., 15., sqrt(lightDist));
        }

        // reflection
        if(reflectivity > 0.){
            totCol += col * (1.-reflectivity) * mixFactor;
            mixFactor *= reflectivity;
            ro = p;
            rd = reflect(rd, n);
        }

        // refraction
        else if(refractivity > 0.){
            totCol += col * (1.-refractivity) * mixFactor;
            mixFactor *= refractivity;
            ro = p;
            rd = refract2(rd, n, pow(refractionIndex, exterior));
        }

        else{
            totCol += col * mixFactor;
            break;
        }
    }
    return totCol;
}

vec3 rayDir(vec2 uv, vec3 forward, vec3 up, float focal){
    vec3 right = normalize(cross(forward, up));
    up = normalize(cross(right, forward));
    return normalize(focal * forward + uv.x * right + uv.y * up);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord){
    vec2 uv = normalizeCoords(fragCoord);
    vec3 ro = vec3(4.5,2.5,4.5);
    vec3 rd = rayDir(uv, normalize(-ro - vec3(2.0,0.,-1.5)), vec3(0.,1.,0.), FOCAL_LENGTH);

    // render scene
    vec3 col = getColor(ro, rd, fragCoord);

    // saturation
    float l = col.r * 0.2 + col.g * 0.7 + col.b * 0.1;
    vec3 gray = vec3(l,l,l);
    vec3 saturated = clamp(gray + (col - gray) * SATURATION, 0.0, 1.0);
    col = mix(col, saturated, 0.5);

    // gamma correction
    col = pow(col, vec3(1./GAMMA));

    fragColor = vec4(col, 1.0);
}
